'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/balance — available balance and its movement history.
 */
class Balance {
  constructor(client) {
    this.client = client;
  }

  /**
   * Get the current available balance.
   */
  retrieve() {
    return this.client.request('GET', '/v1/balance');
  }

  /**
   * List balance movements (collects, adjustments).
   * @param {object} [params] Query params (e.g. page, limit)
   */
  history(params) {
    return this.client.request('GET', withQuery('/v1/balance/history', params));
  }
}

module.exports = Balance;
